// C Dynamic Allocation
int N = 10;
int* c_data = (int*)malloc(sizeof(int) * N);
if (c_data) {
    c_data[0] = 5;
}
char* c_zeroed = (char*)calloc(N, sizeof(char));
realloc(c_data, sizeof(int) * (N + 5));
free(c_data);
free(c_zeroed);

// C++ Raw Dynamic Allocation
struct Widget {};
Widget* w = new Widget();
delete w;

// C++ Array Allocation
int* array_data = new int[20];
array_data[19] = 99;
delete[] array_data; // Must use []

// C++ RAII (Unique Ownership)
std::unique_ptr<int> ptr = std::make_unique<int>(10);
// Array unique ownership
auto arr_ptr = std::make_unique<double[]>(50);
